@pytest.mark.parametrize('df,kwargs,expected', [(DataFrame([[1, 2, 3], [4, 5, 6], [7, 8, 9]], columns=list('abc')).set_index(['a', 'b']), dict(column_dtypes='float64', index_dtypes={0: 'int32', 1: 'int8'}), np.rec.array([(1, 2, 3.0), (4, 5, 6.0), (7, 8, 9.0)], dtype=[('a', '<i4'), ('b', 'i1'), ('c', '<f8')])), (DataFrame([[1, 2, 3], [4, 5, 6], [7, 8, 9]], columns=MultiIndex.from_tuples([('a', 'd'), ('b', 'e'), ('c', 'f')])), dict(column_dtypes={0: '<U1', 2: 'float32'}, index_dtypes='float32'), np.rec.array([(0.0, '1', 2, 3.0), (1.0, '4', 5, 6.0), (2.0, '7', 8, 9.0)], dtype=[('index', '<f4'), ("('a', 'd')", '<U1'), ("('b', 'e')", '<i8'), ("('c', 'f')", '<f4')])), (DataFrame([[1, 2, 3], [4, 5, 6], [7, 8, 9]], columns=MultiIndex.from_tuples([('a', 'd'), ('b', 'e'), ('c', 'f')], names=list('ab')), index=MultiIndex.from_tuples([('d', -4), ('d', -5), ('f', -6)], names=list('cd'))), dict(column_dtypes='float64', index_dtypes={0: '<U2', 1: 'int8'}), np.rec.array([('d', -4, 1.0, 2.0, 3.0), ('d', -5, 4.0, 5.0, 6.0), ('f', -6, 7, 8, 9.0)], dtype=[('c', '<U2'), ('d', 'i1'), ("('a', 'd')", '<f8'), ("('b', 'e')", '<f8'), ("('c', 'f')", '<f8')]))])
def test_to_records_dtype_mi(self, df, kwargs, expected):
    result = df.to_records(**kwargs)
    tm.assert_almost_equal(result, expected)